script:
export const meta = {
  name: 'feedback-finalize',
  description: 'Finish the feedback pass: consolidate rule checks to one per rule per deliverable, retire stale duplicate ids, fix open criticals, justify cleared bindings, then audit or fully review each task',
  phases: [
    { title: 'Finish', detail: 'one agent per task: consolidate, retire duplicates, fix criticals, justify bindings, validate' },
    { title: 'Audit', detail: 'reviewed tasks: prove no rule was lost; never-reviewed tasks: full two-lens review' },
    { title: 'Repair', detail: 'fix every real problem found, re-validate' },
    { title: 'Re-verify', detail: 'fresh check wherever a critical was found' },
  ],
}

const FB = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/e4e5b6fa-8315-4aad-9a2e-58b8b08d9714/scratchpad/feedback'
const G5 = '/Users/dhiren/Documents/ChatGPT/Adobe_Gpt/publish/creative-ai-benchmark/docs/gatsby-v5'
const V3 = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads/input_assets_v3'
const VALIDATE = (id) => `python3 ${FB}/apply_feedback.py --only ${id}`
const builderOf = (id) => id === 'PHOTO-04' ? `${FB}/build_photo04_patch.py` : `${FB}/builders/${id}.py`

const FINISH = {
  type: 'object',
  properties: {
    task_id: { type: 'string' }, validator: { type: 'string' },
    rule_checks_before: { type: 'number' }, rule_checks_after: { type: 'number' },
    merges: { type: 'array', items: { type: 'string' } },
    duplicates_retired: { type: 'number' },
    criticals_fixed: { type: 'array', items: { type: 'string' } },
    bindings_cleared_justified: { type: 'number' }, bindings_restored: { type: 'number' },
    concerns: { type: 'array', items: { type: 'string' } },
  },
  required: ['task_id', 'validator', 'rule_checks_before', 'rule_checks_after', 'merges', 'duplicates_retired', 'criticals_fixed', 'concerns'],
}
const PROBLEMS = {
  type: 'object',
  properties: {
    task_id: { type: 'string' }, lens: { type: 'string' },
    problems: { type: 'array', items: { type: 'object', properties: {
      severity: { type: 'string', enum: ['critical', 'major', 'minor'] }, where: { type: 'string' },
      problem: { type: 'string' }, fix: { type: 'string' } }, required: ['severity', 'where', 'problem', 'fix'] } },
    verdict: { type: 'string' },
  },
  required: ['task_id', 'lens', 'problems', 'verdict'],
}
const REPAIR = {
  type: 'object',
  properties: {
    task_id: { type: 'string' }, fixed: { type: 'array', items: { type: 'string' } },
    not_fixed: { type: 'array', items: { type: 'object', properties: { problem: { type: 'string' }, why: { type: 'string' } }, required: ['problem', 'why'] } },
    validator: { type: 'string' },
  },
  required: ['task_id', 'fixed', 'not_fixed', 'validator'],
}
const REVERIFY = {
  type: 'object',
  properties: { task_id: { type: 'string' }, still_broken: { type: 'array', items: { type: 'string' } },
    new_critical: { type: 'array', items: { type: 'string' } }, verdict: { type: 'string' } },
  required: ['task_id', 'still_broken', 'new_critical', 'verdict'],
}

function finishPrompt(t) {
  const extra = []
  if (t.dups) extra.push(`- ${t.id} carries duplicate check ids. Resolve every one per FINALIZE.md section 2; the validator rejects the task until you do.`)
  if (t.criticals.length) extra.push(`- Fix these open critical findings exactly, from the files (FINALIZE.md section 3). Where a finding is about the per-task OUTPUT_REGISTER.json or DELIVERABLES.md durations, that drift is now fixed by the tool itself; do not work around it:\n${JSON.stringify(t.criticals, null, 1)}`)
  return `Finish the feedback patch for task ${t.id}. Read FIRST: ${FB}/FINALIZE.md, then ${FB}/GUIDE.md for the ground rules.
Patch: ${FB}/patches/${t.id}.json. Builder: ${builderOf(t.id)} (edit it and re-run it; values stay copied from files). Frozen pre-pass copy for reference only: ${FB}/patches_pre_consolidation/${t.id}.json.
Task files: ${G5}/tasks/${t.id}/ (TASK_SPEC.json, VERIFIERS.json). Supplied files: ${V3}/${t.id}/assets/ and ${V3}/${t.id}/asset_plan.json.

Do the four things in FINALIZE.md:
1. Consolidate K2_Q3 type and palette rule checks to ONE check per rule per deliverable, naming every text role it covers. Never drop a rule.
2. Resolve duplicate check ids if any exist (checks_retire).
3. Fix any open critical findings listed below.
4. Justify in change_log every existing binding the patch clears, or restore it.
${extra.join('\n')}
Do not redo or undo the earlier reviewed work beyond this. Never touch automatic checks. Never edit anything under docs/gatsby-v5. No em or en dashes.
Finish with ${VALIDATE(t.id)}: it must print "accepted: 1" with no duplicate-id rejection. Count K2_Q3 checks in checks_add plus checks_modify before and after, and return the summary.`
}

function auditPrompt(t, fin) {
  return `Audit the finishing pass on task ${t.id}. Read ${FB}/FINALIZE.md and ${FB}/GUIDE.md first.
Compare the frozen pre-pass patch ${FB}/patches_pre_consolidation/${t.id}.json with the current patch ${FB}/patches/${t.id}.json. Use the task's TASK_SPEC.json and VERIFIERS.json under ${G5}/tasks/${t.id}/ and the supplied files under ${V3}/${t.id}/.
The finisher reported: ${JSON.stringify(fin).slice(0, 3000)}

You are a skeptic. Report only real problems with severity, where, what, and the exact fix. Do not edit files.
1. NO RULE LOST (critical if violated): for every deliverable, list the distinct rules its K2_Q3 checks covered before (existing checks count) and confirm each is still covered after. Remember the tool now samples templated runs (groups of more than 6 outputs) down to the first output, the last output and outputs with a K1_Q5 check; a rule missing ONLY on an output the tool samples out is not a loss.
2. MERGES ARE TRUE: each merged check states one rule, names every text role it covers, is objective, at most 40 words, no em or en dash, and did not change what passes or fails beyond joining the parts.
3. Nothing outside K2_Q3 was consolidated, sampled away, or rewritten.
4. Duplicate ids resolved correctly: the retired copy is the stale one, judged against the brief and files.
5. Any listed critical is genuinely fixed: ${JSON.stringify(t.criticals).slice(0, 4000)}
6. Every cleared existing binding names a real trap in change_log; otherwise it should have been restored.
7. Run ${VALIDATE(t.id)}; anything but "accepted: 1" is critical.`
}

function lensPrompt(t, lens) {
  const common = `Independently review the feedback patch for task ${t.id}, which has never been reviewed. Read ${FB}/GUIDE.md and ${FB}/FINALIZE.md first. Then read the patch ${FB}/patches/${t.id}.json and its builder ${builderOf(t.id)}, the task's TASK_SPEC.json and VERIFIERS.json under ${G5}/tasks/${t.id}/, its asset_plan.json, and EVERY data or text file in ${V3}/${t.id}/assets/.
You are a skeptic: re-derive from the files. Report only real problems with severity (critical, major, minor), where, what, and the exact fix. Do not edit files.`
  if (lens === 'grounding') return `${common}
LENS: GROUNDING AND TRAPS. Every value in every check, pin and binding copied correctly from the files (a wrong value is critical). Each sentence edit resolves an ambiguity no supplied source settles; a pin that gives away a trap a source settles, or removes an engineered defect, is critical; a genuine unresolvable ambiguity left unpinned is major. No new source_record; no binding that exposes a correction. Palette rules grounded in the brand identity and supplied brand files. No check contradicts the brief or another check. Quotes from files are verbatim.`
  return `${common}
LENS: COVERAGE, NAMING AND FORM. Each type and palette rule has ONE check per deliverable the policy selects (every output of a group of 6 or fewer; for larger groups the tool keeps the first, the last and K1_Q5 outputs). Consistency: requirements checked on one deliverable are checked on every deliverable they apply to; content checks on every output. Asset checks name exact filenames, never groups; full record names. Stale typography evidence refreshed. Form: one fact, Yes or No, at most 40 words, “<name>” (<file>), no em or en dash, correct k_id, no duplicates, no automatic check modified, no duplicate ids. Run ${VALIDATE(t.id)}; anything but "accepted: 1" is critical.`
}

function repairPrompt(t, problems) {
  return `Repair the feedback patch for task ${t.id}. Read ${FB}/FINALIZE.md and ${FB}/GUIDE.md. Patch ${FB}/patches/${t.id}.json, builder ${builderOf(t.id)} (fix the builder and re-run it).
Fix every real problem below; if one is not real, leave it and explain with evidence from the files.
${JSON.stringify(problems, null, 1).slice(0, 24000)}
Never drop a rule, never touch automatic checks, never edit docs/gatsby-v5, no em or en dashes. Finish with ${VALIDATE(t.id)} until it prints "accepted: 1" with no duplicate-id rejection.`
}

function reverifyPrompt(t, critical) {
  return `Adversarially confirm a repair for task ${t.id}. Read ${FB}/FINALIZE.md and ${FB}/GUIDE.md, the CURRENT patch ${FB}/patches/${t.id}.json, and the task's files and supplied files under ${G5}/tasks/${t.id}/ and ${V3}/${t.id}/.
Critical problems reported before the repair:
${JSON.stringify(critical, null, 1).slice(0, 12000)}
For each, is it now genuinely fixed? Then look for any NEW critical problem (a lost rule, a wrong value, a trap given away, a contradiction). Run ${VALIDATE(t.id)} and report its result. Do not edit files.`
}

phase('Finish')
log(`finishing ${args.length} tasks under client decision B`)

const results = await pipeline(
  args,
  (t) => agent(finishPrompt(t), { label: `finish:${t.id}`, phase: 'Finish', schema: FINISH }),
  async (fin, t) => {
    if (!fin) return { id: t.id, fin: null }
    if (t.never_reviewed) {
      const lenses = await parallel(['grounding', 'coverage'].map(l => () =>
        agent(lensPrompt(t, l), { label: `review-${l}:${t.id}`, phase: 'Audit', schema: PROBLEMS })))
      return { id: t.id, fin, reviews: lenses.filter(Boolean) }
    }
    const aud = await agent(auditPrompt(t, fin), { label: `audit:${t.id}`, phase: 'Audit', schema: PROBLEMS })
    return { id: t.id, fin, reviews: aud ? [aud] : [] }
  },
  async (r, t) => {
    if (!r.fin) return r
    const problems = r.reviews.flatMap(v => (v.problems || []).map(p => ({ ...p, lens: v.lens })))
    const real = problems.filter(p => p.severity !== 'minor' || t.never_reviewed)
    if (!real.length) return { ...r, problems, repair: null }
    const repair = await agent(repairPrompt(t, real), { label: `repair:${t.id}`, phase: 'Repair', schema: REPAIR })
    return { ...r, problems, repair }
  },
  async (r, t) => {
    if (!r.fin) return r
    const critical = (r.problems || []).filter(p => p.severity === 'critical')
    if (!critical.length) return { ...r, reverify: null }
    const rv = await agent(reverifyPrompt(t, critical), { label: `reverify:${t.id}`, phase: 'Re-verify', schema: REVERIFY })
    return { ...r, reverify: rv }
  }
)

const done = results.filter(r => r && r.fin)
const missing = results.map((r, i) => (!r || !r.fin) ? args[i].id : null).filter(Boolean)
const unresolved = done.filter(r => r.reverify && ((r.reverify.still_broken || []).length || (r.reverify.new_critical || []).length))
const sev = { critical: 0, major: 0, minor: 0 }
done.forEach(r => (r.problems || []).forEach(p => { sev[p.severity] = (sev[p.severity] || 0) + 1 }))
const before = done.reduce((n, r) => n + (r.fin.rule_checks_before || 0), 0)
const after = done.reduce((n, r) => n + (r.fin.rule_checks_after || 0), 0)
log(`finished ${done.length}/${args.length}; rule checks ${before} -> ${after}; problems critical ${sev.critical}, major ${sev.major}, minor ${sev.minor}; unresolved ${unresolved.length}`)
if (missing.length) log(`WARNING: no result for ${missing.join(', ')}`)

return {
  finished: done.length, missing,
  rule_checks: { before, after },
  problems_found: sev,
  repaired: done.filter(r => r.repair).map(r => r.id),
  unresolved: unresolved.map(r => ({ id: r.id, still_broken: r.reverify.still_broken, new_critical: r.reverify.new_critical })),
  not_fixed: done.filter(r => r.repair && (r.repair.not_fixed || []).length).map(r => ({ id: r.id, not_fixed: r.repair.not_fixed })),
  per_task: done.map(r => ({ id: r.id, before: r.fin.rule_checks_before, after: r.fin.rule_checks_after,
    dups: r.fin.duplicates_retired, criticals: r.fin.criticals_fixed, restored: r.fin.bindings_restored || 0,
    concerns: r.fin.concerns, problems: (r.problems || []).length,
    validator: (r.repair && r.repair.validator) || r.fin.validator })),
}
